mapper.insert:
insert into sys_file (name, stream , type, project_id) values
(#{item.name},#{item.stream},#{item.type},#{item.projectId}) ;
delete from sys_file where id in ( select id from ( SELECT f1.id FROM sys_file f1 join sys_file f2 on f1.name=f2.name and f1.stream=f2.stream and f1.project_id=f2.project_id and f1.id > f2. id ) as f1f2i )
